static func _poly_point(poly: Array, s: float) -> Array:
	if poly.is_empty():
		return [Vector2.ZERO, Vector2.RIGHT]
	var left := maxf(0.0, s)
	for i in range(1, poly.size()):
		var a: Vector2 = poly[i - 1]
		var b: Vector2 = poly[i]
		var l := a.distance_to(b)
		if left <= l:
			return [a + (b - a) * (left / maxf(l, 0.000001)), (b - a).normalized()]
		left -= l
	return [poly[-1], Vector2.RIGHT]

